import{_ as a,o as S,c as r,j as t,a as E}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"ES6 与 ECMAScript 2015 的关系","description":"ES6 既是一个历史名词，也是一个泛指，含义是 5.1 版以后的 JavaScript 的下一代标准，涵盖了 ES2015、ES2016、ES2017 等等，而 ES2015 则是正式名称，特指该年发布的正式版本的语言标准。本书中提到 ES6 的地方，一般是指 ES2015 标准。","frontmatter":{"title":"ES6 与 ECMAScript 2015 的关系","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","语言与运行时"],"description":"ES6 既是一个历史名词，也是一个泛指，含义是 5.1 版以后的 JavaScript 的下一代标准，涵盖了 ES2015、ES2016、ES2017 等等，而 ES2015 则是正式名称，特指该年发布的正式版本的语言标准。本书中提到 ES6 的地方，一般是指 ES2015 标准。","sidebarWeight":15,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/概述/历史与版本/ES6 与 ECMAScript 2015 的关系.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/01-语言与运行时/历史与版本/ES6 与 ECMAScript 2015 的关系.md","filePath":"posts/JavaScript系统教程/01-语言与运行时/历史与版本/ES6 与 ECMAScript 2015 的关系.md"}'),c={name:"posts/JavaScript系统教程/01-语言与运行时/历史与版本/ES6 与 ECMAScript 2015 的关系.md"};function i(p,e,s,l,o,n){return S(),r("div",null,[...e[0]||(e[0]=[t("div",null,[t("h1",{id:"es6-与-ecmascript-2015-的关系",tabindex:"-1"},[E("ES6 与 ECMAScript 2015 的关系 "),t("a",{class:"header-anchor",href:"#es6-与-ecmascript-2015-的关系","aria-label":'Permalink to "ES6 与 ECMAScript 2015 的关系"'},"​")]),t("blockquote",null,[t("p",null,"本节目标：理解“ES6 与 ECMAScript 2015 的关系”的核心思路，并能把它用于实际开发或面试表达。 ES6 既是一个历史名词，也是一个泛指，含义是 5.1 版以后的 JavaScript 的下一代标准，涵盖了 ES2015、ES2016、ES2017 等等，而 ES2015 则是正式名称，特指该年发布的正式版本的语言标准。本书中提到 ES6 的地方，一般是指 ES2015 标准，但有时也是泛指“下一代 JavaScript 语言”。")]),t("p",null,"在标准制定过程中，往往有很多组织和个人不断提交新功能，因此不可能在一个版本里面包括所有将要引入的功能。"),t("p",null,"常规的做法是先发布 6.0 版，过一段时间再发 6.1 版，然后是 6.2 版、6.3 版等等。"),t("p",null,"但是，标准的制定者想让标准的升级成为常规流程：任何人在任何时候，都可以向标准委员会提交新语法的提案，然后标准委员会每个月开一次会，评估这些提案是否可以接受，需要哪些改进。如果经过多次会议以后，一个提案足够成熟了，就可以正式进入标准了。这就是说，标准的版本升级成为了一个不断滚动的流程，每个月都会有变动。"),t("p",null,"标准委员会最终决定，标准在每年的 6 月份正式发布一次，作为当年的正式版本。接下来的时间，就在这个版本的基础上做改动，直到下一年的 6 月份，草案就自然变成了新一年的版本。这样一来，就不需要以前的版本号了，只要用年份标记就可以了。"),t("p",null,"ES6 的第一个版本，在 2015 年 6 月发布了，正式名称就是《ECMAScript 2015 标准》（简称 ES2015）。2016 年 6 月，小幅修订的《ECMAScript 2016 标准》（简称 ES2016）如期发布，这个版本可以看作是 ES6.1 版，因为两者的差异非常小（只新增了数组实例的==includes==方法和指数运算符），基本上是同一个标准。根据计划，2017 年 6 月发布 ES2017 标准。")],-1)])])}const _=a(c,[["render",i]]);export{u as __pageData,_ as default};
